const issue = $json;
const ticketId = issue.id || '';
const creatorEmail = issue.creator?.email || '';
const creatorSlackUsername = creatorEmail ? creatorEmail.split('@')[0] : '';
const identifier = issue.identifier || '';
const url = issue.url || (identifier ? `https://linear.app/n8n/issue/${identifier}` : '');
return {
  json: {
    ticketId,
    ticketIdentifier: identifier,
    title: issue.title || '',
    description: issue.description || '',
    assigneeEmail: issue.assignee?.email || '',
    assigneeName: issue.assignee?.name || 'there',
    creatorId: issue.creator?.id || '',
    creatorDisplayName: issue.creator?.displayName || issue.creator?.name || '',
    creatorEmail,
    creatorSlackUsername,
    url,
    labels: (issue.labels?.nodes || []).map(l => l.name),
    state: issue.state?.name || '',
    priority: issue.priority || 0,
    priorityLabel: issue.priorityLabel || '',
    team: issue.team?.name || '',
    sessionId: 'linear-' + ticketId
  }
};

const t = $('Loop Over Tickets').item.json;
const existing = $('Check Data Table').item.json || {};
const prevAttempts = Number(existing.attempts) || 0;
const attempts = prevAttempts >= 1 ? prevAttempts + 1 : 1;
const prevStatus = existing.status || '';
const isRevision = prevStatus === 'BUILD_COMPLETE';
const isReturning = !isRevision && attempts > 1;

let chatInput;

if (isRevision) {
  // Ticket was previously completed and moved back to To Do with feedback
  const prevWorkflowIds = existing.workflowIds ? JSON.parse(existing.workflowIds) : [];
  const prevSummary = existing.summary || '';

  chatInput = `REVISION REQUEST for ${t.ticketIdentifier} - ${t.title}

This ticket was previously completed and has been sent back for revision. The reviewer has moved it back to "To Do" with updated feedback in the description.

PREVIOUS BUILD CONTEXT:
- Previous summary: ${prevSummary}
- Workflows modified in previous iteration: ${prevWorkflowIds.length > 0 ? prevWorkflowIds.join(', ') : 'none recorded'}
- This is iteration #${attempts}

CURRENT TICKET DESCRIPTION (includes reviewer feedback):
${t.description || ''}

Please review the feedback, locate the workflows from the previous iteration, and make the requested changes. This is a revision to existing work, not a fresh build.`;
} else if (isReturning) {
  chatInput = `Follow-up on ${t.ticketIdentifier} - ${t.title}. This ticket previously needed clarification and has been updated. The current description is:\n\n${t.description || ''}\n\nPlease review and proceed with the build.`;
} else {
  chatInput = `Build the following from this Linear ticket:\n\nTicket: ${t.ticketIdentifier} — ${t.title}\nURL: ${t.url}\n\nDescription:\n${t.description || ''}\n\nLabels: ${(t.labels || []).join(', ')}\nPriority: ${t.priorityLabel}\nTeam: ${t.team}\nRequester: ${t.assigneeName}\n\nPlease review this ticket and build what is requested.`;
}

chatInput += '\n\nWhen you are done, respond with a JSON block in this exact format:\n```json\n{\n  "status": "NEEDS_CLARIFICATION" | "BUILD_COMPLETE" | "BUILD_FAILED",\n  "summary": "what was done or what is needed",\n  "workflowIds": ["affected workflow IDs"],\n  "testResults": "test outcome details",\n  "manualSteps": ["any manual steps needed"],\n  "clarificationComment": "questions for the ticket author (only if NEEDS_CLARIFICATION)"\n}\n```';

return {
  json: {
    chatInput,
    sessionId: t.sessionId,
    channel: 'C0BN97ZSKKJ',
    env: 'slack',
    ticketId: t.ticketId,
    ticketIdentifier: t.ticketIdentifier,
    title: t.title,
    url: t.url,
    assigneeName: t.assigneeName,
    assigneeEmail: t.assigneeEmail,
    creatorId: t.creatorId,
    creatorDisplayName: t.creatorDisplayName,
    creatorEmail: t.creatorEmail,
    creatorSlackUsername: t.creatorSlackUsername,
    attempts,
    isRevision
  }
};

const raw = $json;
const t = $('Build Chat Input').item.json;

let text;
if (typeof raw === 'string') { text = raw; }
else if (raw.output) { text = raw.output; }
else if (raw.response) { text = raw.response; }
else if (raw.error || raw.message) { text = 'ERROR: ' + (raw.error?.message || raw.message || JSON.stringify(raw)); }
else { text = JSON.stringify(raw); }

const hadError = !!(raw && (raw.error || (typeof raw.output === 'undefined' && typeof raw.message === 'string')));

let parsed = null;
const fence = text.match(/```json\s*([\s\S]*?)```/i) || text.match(/```\s*([\s\S]*?)```/i);
if (fence) { try { parsed = JSON.parse(fence[1].trim()); } catch (e) { parsed = null; } }
if (!parsed) {
  const brace = text.match(/\{[\s\S]*\}/);
  if (brace) { try { parsed = JSON.parse(brace[0]); } catch (e) { parsed = null; } }
}

let status, summary, workflowIds, testResults, manualSteps, clarificationComment;
if (parsed && parsed.status) {
  status = String(parsed.status).toUpperCase();
  summary = parsed.summary || '';
  workflowIds = Array.isArray(parsed.workflowIds) ? parsed.workflowIds : [];
  testResults = parsed.testResults || '';
  manualSteps = Array.isArray(parsed.manualSteps) ? parsed.manualSteps : [];
  clarificationComment = parsed.clarificationComment || '';
} else {
  const lower = text.toLowerCase();
  if (lower.startsWith('error:') || lower.includes('failed') || lower.includes('could not') || lower.includes('unable to')) { status = 'BUILD_FAILED'; }
  else if (lower.includes('clarification') || lower.includes('unclear') || lower.includes('need more info') || lower.includes('can you clarify')) { status = 'NEEDS_CLARIFICATION'; }
  else { status = 'BUILD_COMPLETE'; }
  summary = text.substring(0, 1000);
  workflowIds = [];
  testResults = '';
  manualSteps = [];
  clarificationComment = status === 'NEEDS_CLARIFICATION' ? text : '';
}
if (hadError) { status = 'BUILD_FAILED'; if (!summary) { summary = text.substring(0, 1000); } }
if (!['NEEDS_CLARIFICATION','BUILD_COMPLETE','BUILD_FAILED'].includes(status)) { status = 'UNKNOWN'; }

return {
  json: {
    status,
    summary,
    workflowIds,
    testResults,
    manualSteps,
    clarificationComment,
    rawOutput: text,
    ticketId: t.ticketId,
    ticketIdentifier: t.ticketIdentifier,
    title: t.title,
    url: t.url,
    assigneeName: t.assigneeName,
    creatorId: t.creatorId,
    creatorDisplayName: t.creatorDisplayName,
    creatorEmail: t.creatorEmail,
    creatorSlackUsername: t.creatorSlackUsername,
    sessionId: t.sessionId
  }
};

